update public.exercise_questions set question_text='Após uma atividade, um professor devolve ao estudante informações específicas sobre o que foi compreendido, o que precisa ser revisto e qual pode ser o próximo passo. Um feedback educativo é mais útil quando', feedback_hint='Um feedback formativo descreve aspectos relevantes do desempenho e ajuda o estudante a identificar como avançar, em vez de apenas informar acerto ou erro.', updated_at=now() where id='c2872f94-cc37-40fa-b0f2-96c19deebe55';